\title{The Algebra of Sheaf Imputation: Partial Sections, Left-Regular Bands,
and the Local Certificate of Consistent Completion}
\author{Aristotle}
\date{June 19, 2026}

\begin{document}
\begin{abstract}
We model a database row with missing entries as a \emph{partial section} of a
discrete sheaf of records, $\PS\,\iota\,\alpha := \iota \to \Opt\,\alpha$, and
study the left-biased merge $\glue$ that overlays one record on another. We prove
that partial sections form an idempotent monoid under $\glue$ with the
all-missing row $\emptyset$ as two-sided identity, and that they satisfy the two
defining identities of a left-regular band, $\glue(\glue\,f\,g)\,f = \glue\,f\,g$
and $\glue\,f\,(\glue\,g\,f) = \glue\,f\,g$. We then establish the \emph{sheaf
condition for databases}: a family of records admits a global section---a
consistent completion extending every member---if and only if it is pairwise
compatible. We complement existence with uniqueness (the greedy merge is the
unique global section bounded by the union of supports) and a locality principle.
All results hold for arbitrary index and value types with no finiteness,
ordering, or topology. We give proof sketches, an imputation algorithm with
complexity analysis, and a probabilistic model $P(\text{consistent}) = (1-r)^N$
predicting an exponential feasibility cliff.
\end{abstract}

\maketitle

\section{Introduction}
Imputation---the completion of missing entries in a dataset---is ubiquitous and
usually treated heuristically (mean substitution, $k$-nearest-neighbour copying,
chained equations). We argue that its combinatorial backbone is algebraic and
sheaf-theoretic, yielding a local, checkable certificate for the existence of a
consistent completion and a canonical, unique completion when one exists.

A record over a column-index set $\iota$ with values in $\alpha$ is a function
$\iota \to \Opt\,\alpha$. The overlay merge $\glue$ is the operation a
practitioner performs when layering one record over another. Our thesis: this
operation is a left-regular band, and the sheaf gluing axiom, specialised to this
setting, states exactly that local (pairwise) compatibility implies global
consistency.

\paragraph{Contributions.}
(1) Monoid and band structure of $(\PS\,\iota\,\alpha, \glue, \emptyset)$;
(2) the sheaf condition: existence of a global section $\Leftrightarrow$ pairwise
compatibility, with explicit greedy construction;
(3) uniqueness and locality;
(4) a probabilistic feasibility model $P = (1-r)^N$ with an exponential-cliff
conjecture.

\section{Definitions}
Throughout $\iota$ is a type of column indices, $\alpha$ a type of values, and
$\kappa$ an index type for families. We use $\Opt\,\alpha$ with constructors
$\some\,a$ (present) and $\none$ (missing).

\begin{definition}[Partial section]
$\PS\,\iota\,\alpha := \iota \to \Opt\,\alpha$. A record assigns to each column a
value or ``missing''.
\end{definition}
\begin{definition}[Support]
$\Supp\,f := \{\, i \mid f(i) \neq \none \,\}$, the filled columns.
\end{definition}
\begin{definition}[Compatibility]
$\Compatible\,f\,g :\Leftrightarrow \forall i,\ f(i)\neq\none \to g(i)\neq\none
\to f(i) = g(i)$.
\end{definition}
\begin{definition}[Extension]
$\Extends\,g\,f :\Leftrightarrow \forall i,\ f(i)\neq\none \to g(i) = f(i)$.
\end{definition}
\begin{definition}[Binary glue]
$\glue\,f\,g := \lambda i.\ \mathbf{match}\ f(i)\ \mathbf{with}\ \some\,a
\Rightarrow \some\,a \mid \none \Rightarrow g(i)$.
\end{definition}
\begin{definition}[Pairwise compatibility]
For $s : \kappa \to \PS\,\iota\,\alpha$,\ $\mathrm{PairwiseCompatible}\,s
:\Leftrightarrow \forall j\,k,\ \Compatible\,(s_j)\,(s_k)$.
\end{definition}
\begin{definition}[Family glue]
$\mathrm{familyGlue}\,s := \lambda i.\ \mathbf{if}\ \exists j,\ s_j(i)\neq\none\
\mathbf{then}\ s_{\mathrm{choose}}(i)\ \mathbf{else}\ \none$.
\end{definition}
\begin{definition}[Empty section]
$\emptyset := \lambda\,\_.\ \none$, the all-missing record.
\end{definition}
\begin{definition}[Global section]
$\mathrm{HasGlobalSection}\,s :\Leftrightarrow \exists h,\ \forall j,\
\Extends\,h\,(s_j)$.
\end{definition}

\begin{lemma}[\texttt{glue\_apply}]
$(\glue\,f\,g)(i) = \mathbf{if}\ f(i)\neq\none\ \mathbf{then}\ f(i)\ \mathbf{else}\
g(i)$.
\end{lemma}
\begin{proof}
Case split on $f(i)$.
\end{proof}

\section{Monoid and band structure}

\begin{theorem}[Identity: \texttt{glue\_emptySection\_left/right}]
$\glue\,\emptyset\,f = f$ and $\glue\,f\,\emptyset = f$.
\end{theorem}
\begin{proof}
By extensionality, check each column. Left: $\emptyset(i)=\none$ falls through to
$f(i)$. Right: if $f(i)=\some\,a$ the merge returns $\some\,a$; if $f(i)=\none$ it
returns $\emptyset(i)=\none=f(i)$.
\end{proof}

\begin{theorem}[Associativity: \texttt{glue\_assoc}]
$\glue\,(\glue\,f\,g)\,h = \glue\,f\,(\glue\,g\,h)$.
\end{theorem}
\begin{proof}
Pointwise nested case analysis on $f(i),g(i)$: all three branches
($f(i)$ present; $f(i)$ absent, $g(i)$ present; both absent) agree.
\end{proof}

\begin{theorem}[Idempotence: \texttt{glue\_idem}]
$\glue\,f\,f = f$.
\end{theorem}
\begin{proof}
Pointwise: $f(i)=\some\,a$ returns $\some\,a$; $f(i)=\none$ falls through to the
second copy, again $\none$.
\end{proof}

\begin{corollary}
$(\PS\,\iota\,\alpha, \glue, \emptyset)$ is an idempotent monoid.
\end{corollary}

\begin{theorem}[Left-regular band laws: \texttt{glue\_band\_left/right}]
$\glue\,(\glue\,f\,g)\,f = \glue\,f\,g$ \ and \ $\glue\,f\,(\glue\,g\,f) =
\glue\,f\,g$.
\end{theorem}
\begin{proof}
Pointwise case split on $f(i),g(i)$. If $f(i)=\some\,a$ the outer re-glue of $f$
already returns $\some\,a=\glue\,f\,g$ at $i$; if $f(i)=\none$, the inner merge
reduces to $g(i)$ and re-gluing $f$ (still $\none$) leaves $g(i)$. With
idempotence and associativity these are the band axioms.
\end{proof}

\begin{remark}[Non-commutativity]
$\glue$ is not commutative: when $f(i),g(i)$ are both present and unequal,
$\glue\,f\,g \neq \glue\,g\,f$. The band laws record left-biased precedence---the
correct semantics for trust-ordered, conflicting sources.
\end{remark}

\section{The sheaf condition}

\begin{proposition}[\texttt{support\_glue\_eq\_union}]
$\Supp(\glue\,f\,g) = \Supp\,f \cup \Supp\,g$.
\end{proposition}

\begin{lemma}[\texttt{glue\_extends\_left}]
$\Extends\,(\glue\,f\,g)\,f$.
\end{lemma}

\begin{lemma}[\texttt{glue\_extends\_right}]
$\Compatible\,f\,g \Rightarrow \Extends\,(\glue\,f\,g)\,g$.
\end{lemma}
\begin{proof}
At a column with $g(i)=\some\,b$: if $f(i)=\none$ the merge returns $g(i)$; if
$f(i)=\some\,a$, compatibility gives $a=b$, so the merge returns $\some\,a=g(i)$.
\end{proof}

\begin{theorem}[Binary sheaf condition: \texttt{compatible\_iff\_exists\_common\_extension}]
$\Compatible\,f\,g \iff \exists h,\ \Extends\,h\,f \wedge \Extends\,h\,g$.
\end{theorem}
\begin{proof}
($\Leftarrow$) A common extension forces $f(i)=h(i)=g(i)$ wherever both are
defined. ($\Rightarrow$) Take $h:=\glue\,f\,g$; it extends $f$ (Lemma 3) and,
using compatibility, $g$ (Lemma 4).
\end{proof}

\begin{lemma}[\texttt{familyGlue\_extends}]
$\mathrm{PairwiseCompatible}\,s \Rightarrow \forall j,\
\Extends\,(\mathrm{familyGlue}\,s)\,(s_j)$.
\end{lemma}
\begin{proof}
At $i$ with $s_j(i)=\some\,a$, $\mathrm{familyGlue}$ selects some $s_k(i)$;
pairwise compatibility of $s_k,s_j$ forces it to equal $a$.
\end{proof}

\begin{theorem}[Sheaf gluing: \texttt{glue\_family\_exists}]
$\mathrm{PairwiseCompatible}\,s \Rightarrow \exists h,\ \forall j,\
\Extends\,h\,(s_j)$; equivalently $\mathrm{HasGlobalSection}\,s$.
\end{theorem}
\begin{proof}
Take $h := \mathrm{familyGlue}\,s$ and apply Lemma~5.
\end{proof}

\noindent\emph{Interpretation.} Global consistency is certified by pairwise
checks: no higher-order conflict escapes pairwise compatibility. The witness is
the greedy merge.

\section{Uniqueness and locality}

\begin{theorem}[Uniqueness: \texttt{glue\_unique}]
If $\Extends\,h\,f$, $\Extends\,h\,g$, and $\Supp\,h \subseteq \Supp\,f \cup
\Supp\,g$, then $h = \glue\,f\,g$.
\end{theorem}
\begin{proof}
Pointwise. If $f(i)=\some\,a$, then $h(i)=f(i)=(\glue\,f\,g)(i)$. If $f(i)=\none$,
$g(i)=\some\,b$, then $h(i)=g(i)=(\glue\,f\,g)(i)$. If both are $\none$, the
support bound forces $h(i)=\none$, matching the merge.
\end{proof}

\begin{remark}[Load-bearing bound]
Without the support bound, any extension inventing values in unmentioned columns
is also a common extension; the bound encodes honest imputation and is necessary.
\end{remark}

\begin{theorem}[Locality: \texttt{restrict\_locality}]
$\Extends\,f\,g \wedge \Extends\,g\,f \Rightarrow f = g$.
\end{theorem}
\begin{proof}
Pointwise: both $\none$ agree; otherwise the defined side is preserved by mutual
extension.
\end{proof}

\section{The Sheaf Imputation algorithm}
Given records $s_1,\dots,s_m$ over $n$ columns:
\begin{enumerate}
\item \textbf{Feasibility (Theorem 9).} For each pair $(j,k)$ and column $i$,
flag a conflict if both defined and unequal; if any conflict, return
\textsc{infeasible}.
\item \textbf{Completion (Theorems 9, 7).} Start from $\emptyset$; for each
column take the first defined value among $s_1,\dots,s_m$.
\end{enumerate}
Feasibility is $O(m^2 n)$, completion $O(mn)$. By Theorem~9 the scan is sound and
complete; by Theorem~7 the output is the unique support-bounded completion.
Conflicts are reported as concrete $(\text{row},\text{row},\text{column})$
triples.

\section{A probabilistic model}
If a table induces $N$ overlapping pairwise constraints, each independently
satisfied with probability $1-r$, then
\[
P(\text{consistent}) = (1-r)^N,
\]
monotone decreasing in $r$, $N$, and (via the constraint count) the number of
columns $n$, with $(1-r)^N \to 0$ exponentially as $N\to\infty$.

\begin{conjecture}[Sharp feasibility threshold]
With $N = \binom{n}{k}$ independent constraints, feasibility undergoes a sharp
transition at $r^\ast = 1 - N^{-1/N}$: feasibility is $\approx 1$ below $r^\ast$
and $\approx 0$ above it as $n \to \infty$, since $(1-r)^N$ crosses any fixed
level within an $O(1/N)$ window of $r$.
\end{conjecture}

\noindent We treat this formula and threshold as a model/conjecture, distinct
from the verified core of Sections 3--5.

\section{Applications and discussion}
Data fusion and record linkage are exactly $\mathrm{familyGlue}$, with the
pairwise check a principled, certificate-bearing conflict detector. Associativity
and idempotence make $\glue$ safe for incremental, at-least-once federated
integration. The band laws formalise ``first source wins''. The development is
elementary---every law is a per-column case split on $\Opt$---yet recovers exactly
the structure sheaf theory predicts: imputability is a local property, pairwise
agreement is the cocycle condition, and its failure is the obstruction to gluing.

\section{Future work}
(1) Prove the gluing band is the free left-regular band on singleton
cell-assignments; (2) interpret the obstruction cohomologically ($H^0$ = global
sections, $\dim H^1$ = conflict count); (3) establish the sharp threshold
$r^\ast = 1 - \binom{n}{k}^{-1/\binom{n}{k}}$; (4) characterise non-bounded
extensions as band extensions of $\mathrm{familyGlue}$.

\section{Conclusion}
Consistent imputation, at its core, is the gluing of partial sections of a sheaf:
an idempotent left-regular band with the empty record as identity, consistent
completion existing exactly when records are pairwise compatible, and unique on
the cells the data mentions. These proved theorems turn ``fill in the blanks''
into a problem with certificates, canonical answers, and a predictive theory of
solvability.

\end{document}

