function SheafImpute(s_1, ..., s_m):
  # Phase 1 - feasibility certificate (sheaf condition)
  for each pair (j, k) with j < k:
    for each column i defined in both s_j and s_k:
      if s_j[i] != s_k[i]:
        return CONFLICT(j, k, i)
  # Phase 2 - canonical completion (familyGlue, unique by glue_unique)
  h <- empty record            # the band identity emptySection
  for r in 1..m:
    for each column i defined in s_r:
      if i not in h:
        h[i] <- s_r[i]          # first defined value wins
  return h

